import { attach, destroySubtree, getParent } from "../../lib/ecs-js/hierarchy.js";
import { EffectChanged } from "../../events/EffectChanged.js";
import { ActiveEffects } from "../components/ActiveEffects.js";
import { Duration } from "../components/Duration.js";
import { EffectInstance } from "../components/EffectInstance.js";
import { EffectImmunities } from "../components/EffectImmunities.js";
import { PeriodicEffect } from "../components/PeriodicEffect.js";
import { Source } from "../components/Source.js";
import { StatusEffectNode } from "../components/StatusEffectNode.js";
import { TimedEffectNode } from "../components/TimedEffectNode.js";
import { Vitality } from "../components/Vitality.js";
import { Mana } from "../components/Mana.js";
import { Stamina } from "../components/Stamina.js";
import { getEffectDefinition } from "../data/effectInstances.js";
import { applyHealing } from "./applyHealing.js";
import { dealDamage } from "./dealDamage.js";
import { effectiveMaxMana, effectiveMaxStamina } from "./passiveBonuses.js";
import { childrenWith } from "./topology.js";

export function applyEffectInstance(world, actor, effect) {
  const def = getEffectDefinition(effect?.key);
  if (!def) throw new Error(`Unknown effect definition: ${effect?.key}`);
  if (!world.isAlive(actor)) throw new Error("Effect target must be alive");
  const turns = effect.turnsLeft;
  if (turns !== Infinity && (!Number.isInteger(turns) || turns < 1)) throw new Error("Effect duration must be positive");
  const potency = effect.potency ?? 1;
  if (!Number.isFinite(potency) || potency < 0) throw new Error("Effect potency must be non-negative");
  const immunities = world.get(actor, EffectImmunities)?.immuneTo || [];
  if ([def.id, ...def.statuses].some((key) => immunities.includes(key))) return 0;
  const now = Number(world.time || 0);
  let nodeId = 0;
  for (const [id, instance] of childrenWith(world, actor, EffectInstance)) {
    if (instance.definitionId !== def.id || def.stacking === "independent") continue;
    const source = world.get(id, Source);
    if (def.match === "actor" && instance.sourceActorId !== (effect.sourceActorId || 0)) continue;
    if (def.match === "item" && source?.id !== (effect.sourceId || 0)) continue;
    if (def.stacking === "replace" || !(world.get(id, Duration)?.turnsLeft > 0)) {
      removeEffectInstance(world, id, "replaced");
    } else nodeId = id;
    break;
  }
  const refreshed = nodeId > 0;
  if (!refreshed) {
    nodeId = world.create();
    attach(world, nodeId, actor);
    world.add(nodeId, StatusEffectNode, { key: def.id, potency, stacks: 1 });
    world.add(nodeId, TimedEffectNode, { key: def.id });
    world.add(nodeId, Duration, { turnsLeft: turns, maxTurns: turns, startedAtTurn: world.step, onsetLeft: Math.max(0, Number(effect.onsetLeft || 0) | 0) });
    world.add(nodeId, EffectInstance, { definitionId: def.id, sourceActorId: effect.sourceActorId || 0, appliedAt: now, processedAt: now, permanent: turns === Infinity });
    for (const op of def.periodic) {
      const child = world.create();
      attach(world, child, nodeId);
      world.add(child, PeriodicEffect, { ...op, baseAmount: op.amount, amount: op.amount * potency, ticksLeft: op.interval });
    }
  } else {
    const duration = world.get(nodeId, Duration);
    duration.turnsLeft = def.stacking === "extend" ? duration.turnsLeft + turns : Math.max(duration.turnsLeft, turns);
    duration.maxTurns = Math.max(duration.maxTurns, duration.turnsLeft);
    duration.onsetLeft = Math.min(duration.onsetLeft, Math.max(0, Number(effect.onsetLeft || 0) | 0));
    const instance = world.get(nodeId, EffectInstance);
    instance.permanent = duration.turnsLeft === Infinity;
    instance.sourceActorId = effect.sourceActorId || 0;
    const status = world.get(nodeId, StatusEffectNode);
    status.potency = Math.max(status.potency, potency);
    if (def.stacking === "stack") status.stacks = Math.min(def.maxStacks, status.stacks + 1);
    for (const [, op] of childrenWith(world, nodeId, PeriodicEffect)) {
      op.amount = op.baseAmount * status.potency * status.stacks;
    }
  }
  const source = { kind: effect.sourceKind || "", id: effect.sourceId || 0, key: effect.sourceKey || "" };
  if (world.has(nodeId, Source)) world.set(nodeId, Source, source);
  else world.add(nodeId, Source, source);
  world.emit(new EffectChanged({ actor, instanceId: nodeId, key: def.id, phase: refreshed ? "refreshed" : "applied" }));
  return nodeId;
}

export function removeEffectInstance(world, nodeId, reason = "removed") {
  const instance = world.get(nodeId, EffectInstance);
  if (!instance) return false;
  const actor = getParent(world, nodeId);
  // Disable immediately, including when structural destruction is deferred.
  world.get(nodeId, Duration).turnsLeft = 0;
  world.emit(new EffectChanged({ actor, instanceId: nodeId, key: instance.definitionId, phase: "removed", reason }));
  destroySubtree(world, nodeId);
  return true;
}

export function snapshotEffectInstances(world, actor) {
  const rows = [];
  for (const [id, instance] of childrenWith(world, actor, EffectInstance)) {
    const duration = world.get(id, Duration);
    if (!(duration?.turnsLeft > 0) || duration.onsetLeft > 0) continue;
    const status = world.get(id, StatusEffectNode);
    const source = world.get(id, Source);
    rows.push({ instanceId: id, key: instance.definitionId, turns: duration.turnsLeft, stacks: status.stacks, potency: status.potency, sourceId: source?.id || 0, sourceKey: source?.key || "" });
  }
  return rows;
}

// Old saves and legacy producers enter through this same materialization path.
export function migrateLegacyEffectInstances(world) {
  for (const [actor, active] of world.query(ActiveEffects)) {
    const retained = [];
    for (const effect of active.effects) {
      if (!getEffectDefinition(effect?.key)) { retained.push(effect); continue; }
      if (effect.turnsLeft > 0) applyEffectInstance(world, actor, effect);
    }
    if (retained.length !== active.effects.length) active.effects = retained;
  }
}

export function tickEffectInstances(world) {
  const now = Number(world.time || 0);
  for (const [id, instance, duration] of world.query(EffectInstance, Duration)) {
    const actor = getParent(world, id);
    if (!world.isAlive(actor) || world.get(actor, Vitality)?.hp <= 0) {
      removeEffectInstance(world, id, "death");
      continue;
    }
    if (!(duration.turnsLeft > 0)) { removeEffectInstance(world, id, "expired"); continue; }
    if (instance.processedAt === now || instance.appliedAt === now) continue;
    instance.processedAt = now;
    if (duration.onsetLeft > 0) { duration.onsetLeft--; continue; }
    for (const [, op] of childrenWith(world, id, PeriodicEffect)) {
      op.ticksLeft--;
      if (op.ticksLeft > 0) continue;
      op.ticksLeft = op.interval;
      const source = instance.sourceActorId;
      if (op.operation === "damage") dealDamage(world, { target: actor, source, amount: op.amount, type: op.damageType, cause: instance.definitionId });
      else if (op.operation === "heal") applyHealing(world, { target: actor, source, amount: op.amount, cause: instance.definitionId });
      else {
        const isMana = op.operation.startsWith("mana_");
        const Comp = isMana ? Mana : Stamina;
        const resource = world.get(actor, Comp);
        if (!resource) continue;
        const field = isMana ? "mana" : "stamina";
        const cap = isMana ? effectiveMaxMana(world, actor, resource) : effectiveMaxStamina(world, actor, resource);
        const amount = op.operation.endsWith("_drain") ? -op.amount : op.amount;
        resource[field] = Math.max(0, Math.min(cap, resource[field] + amount));
      }
    }
    if (duration.turnsLeft !== Infinity) duration.turnsLeft--;
    if (duration.turnsLeft <= 0) removeEffectInstance(world, id, "expired");
  }
}

// JSON encodes Infinity as null. The explicit lifecycle flag restores permanence.
export function normalizeEffectSnapshot(snapshot) {
  const permanent = new Set((snapshot?.comps?.EffectInstance || []).filter(([, row]) => row.permanent).map(([id]) => id));
  if (!permanent.size) return snapshot;
  return { ...snapshot, comps: { ...snapshot.comps, Duration: (snapshot.comps.Duration || []).map(([id, row]) => permanent.has(id) ? [id, { ...row, turnsLeft: Infinity, maxTurns: Infinity }] : [id, row]) } };
}
import { assert, assertEquals, assertThrows } from "jsr:@std/assert";
import { World } from "../src/lib/ecs-js/index.js";
import { serializeWorld } from "../src/lib/ecs-js/serialization.js";
import { ActiveEffects, Duration, EffectInstance, PeriodicEffect, Player, Position, Stamina, Vitality } from "../src/rules/components/index.js";
import { Mana } from "../src/rules/components/Mana.js";
import { EffectChanged } from "../src/events/EffectChanged.js";
import { registerEffectDefinition } from "../src/rules/data/effectInstances.js";
import { effectSystem } from "../src/rules/systems/effectSystem.js";
import { cleanupSystem } from "../src/rules/systems/cleanupSystem.js";
import { applyEffectInstance, removeEffectInstance, snapshotEffectInstances } from "../src/rules/utils/effectInstances.js";
import { statusStrength } from "../src/rules/utils/statusFacade.js";
import { buildEffectRows } from "../src/main/ui/effectRows.js";
import { getSavegameRegistryNames } from "../src/main/wiring/savegameSerializationRegistry.js";
import { restoreSnapshotFromSavegame } from "../src/main/wiring/savegameLoad.js";

registerEffectDefinition("test_composite_drain", {
  statuses: ["hastened"],
  periodic: [{ operation: "damage", amount: 2, interval: 2 }, { operation: "mana_drain", amount: 3, interval: 3 }],
});
registerEffectDefinition("test_independent", { stacking: "independent", periodic: [] });
registerEffectDefinition("test_by_source", { match: "actor", statuses: ["weakened"], periodic: [] });
registerEffectDefinition("test_stack", { stacking: "stack", maxStacks: 2, periodic: [{ operation: "heal", amount: 2 }, { operation: "mana_drain", amount: 3 }] });
registerEffectDefinition("test_extend", { stacking: "extend", periodic: [] });
registerEffectDefinition("test_replace", { stacking: "replace", periodic: [] });

function setup() {
  const world = new World({ seed: 613 });
  world.setScheduler(effectSystem);
  const actor = world.create();
  world.add(actor, Player, {});
  world.add(actor, Position, { x: -8, y: -8 });
  world.add(actor, Vitality, { hp: 10, maxHp: 100 });
  world.add(actor, Stamina, { stamina: 0, maxStamina: 100, staminaRegen: 0 });
  world.add(actor, Mana, { mana: 30, maxMana: 30 });
  return { world, actor };
}

Deno.test("effect instances retain composite identity after source consumption and clean up all children", () => {
  const { world, actor } = setup();
  const source = world.create();
  const phases = [];
  world.on(EffectChanged, (event) => phases.push(event.phase));
  const instance = applyEffectInstance(world, actor, { key: "town_stew", turnsLeft: 3, sourceId: source, sourceKey: "food_stew" });
  world.destroy(source);
  assertEquals(world.get(actor, ActiveEffects), null);
  assertEquals([...world.query(PeriodicEffect)].length, 2);
  assertEquals(buildEffectRows(world, actor).map((row) => [row.name, row.glyph, row.turns]), [["Town Stew", "%", 3]]);
  effectSystem(world); // Same application turn must not tick.
  world.tick(0);
  assertEquals(world.get(actor, Vitality).hp, 10);
  world.tick(1);
  assertEquals(world.get(actor, Vitality).hp, 11);
  assertEquals(world.get(actor, Stamina).stamina, 1);
  assertEquals(statusStrength(world, actor, "town_stew"), 1);
  assertEquals(world.get(instance, Duration).turnsLeft, 2);
  effectSystem(world); // Duplicate resolution in the same turn is harmless.
  assertEquals(world.get(actor, Vitality).hp, 11);
  world.tick(1);
  world.tick(1);
  assertEquals(world.get(actor, Vitality).hp, 13);
  assertEquals(statusStrength(world, actor, "town_stew"), 0);
  assertEquals(buildEffectRows(world, actor), []);
  assertEquals([...world.query(EffectInstance)].length, 0);
  assertEquals([...world.query(PeriodicEffect)].length, 0);
  assertEquals(phases, ["applied", "removed"]);
});

Deno.test("periodic operations have independent cadence and expiration boundaries", () => {
  const { world, actor } = setup();
  applyEffectInstance(world, actor, { key: "test_composite_drain", turnsLeft: 6 });
  for (let turn = 1; turn <= 6; turn++) {
    world.tick(1);
    assertEquals(world.get(actor, Vitality).hp, 10 - Math.floor(turn / 2) * 2);
    assertEquals(world.get(actor, Mana).mana, 30 - Math.floor(turn / 3) * 3);
  }
  assertEquals(snapshotEffectInstances(world, actor), []);
});

Deno.test("refresh preserves periodic cadence, source matching isolates casters, independent instances remain inspectable", () => {
  const { world, actor } = setup();
  const first = applyEffectInstance(world, actor, { key: "town_stew", turnsLeft: 3 });
  world.tick(1);
  assertEquals(applyEffectInstance(world, actor, { key: "town_stew", turnsLeft: 5 }), first);
  assertEquals(world.get(first, Duration).turnsLeft, 5);
  applyEffectInstance(world, actor, { key: "test_by_source", turnsLeft: 2, sourceActorId: 7 });
  applyEffectInstance(world, actor, { key: "test_by_source", turnsLeft: 2, sourceActorId: 8 });
  applyEffectInstance(world, actor, { key: "test_independent", turnsLeft: 2 });
  applyEffectInstance(world, actor, { key: "test_independent", turnsLeft: 2 });
  assertEquals(snapshotEffectInstances(world, actor).length, 5);
  assertEquals(statusStrength(world, actor, "weakened"), 2);
  removeEffectInstance(world, first, "dispelled");
  assertEquals(statusStrength(world, actor, "town_stew"), 0);
});

Deno.test("JSON save/load continues finite and permanent effects with the same tick outcomes and visuals", () => {
  const { world, actor } = setup();
  applyEffectInstance(world, actor, { key: "town_stew", turnsLeft: 5 });
  applyEffectInstance(world, actor, { key: "test_composite_drain", turnsLeft: Infinity });
  world.tick(1);
  world.tick(1);
  const saved = JSON.parse(JSON.stringify({ world: serializeWorld(world, { include: getSavegameRegistryNames(world) }) }));
  const restored = new World({ seed: 613 });
  restoreSnapshotFromSavegame(restored, saved);
  restored.setScheduler(effectSystem);
  assertEquals(buildEffectRows(restored, actor), buildEffectRows(world, actor));
  for (let i = 0; i < 4; i++) {
    world.tick(1);
    restored.tick(1);
    assertEquals(restored.get(actor, Vitality), world.get(actor, Vitality));
    assertEquals(restored.get(actor, Mana), world.get(actor, Mana));
    assertEquals(buildEffectRows(restored, actor), buildEffectRows(world, actor));
  }
  assertEquals(snapshotEffectInstances(restored, actor)[0].turns, Infinity);
});

Deno.test("legacy stew migrates once, onset delays operations, and worlds remain independent", () => {
  const { world, actor } = setup();
  const other = setup();
  world.add(actor, ActiveEffects, { effects: [{ key: "town_stew", turnsLeft: 3, potency: 1, onsetLeft: 1 }] });
  world.tick(1);
  assertEquals(world.get(actor, ActiveEffects).effects, []);
  assertEquals([...world.query(EffectInstance)].length, 1);
  world.tick(1);
  assertEquals(world.get(actor, Vitality).hp, 10);
  world.tick(1);
  assertEquals(world.get(actor, Vitality).hp, 11);
  assertEquals(other.world.get(other.actor, Vitality).hp, 10);
  assertEquals([...other.world.query(EffectInstance)].length, 0);
});

Deno.test("effect definitions reject invalid operations and timing before runtime", () => {
  assertThrows(() => registerEffectDefinition("test_bad_op", { periodic: [{ operation: "typo", amount: 1 }] }));
  assertThrows(() => registerEffectDefinition("test_bad_time", { periodic: [{ operation: "heal", amount: 1, interval: 0 }] }));
  assertThrows(() => applyEffectInstance(setup().world, 1, { key: "town_stew", turnsLeft: 0 }));
});

Deno.test("death after the effects phase removes the complete package before actor IDs can be reused", () => {
  const { world, actor } = setup();
  applyEffectInstance(world, actor, { key: "town_stew", turnsLeft: 5 });
  world.get(actor, Vitality).hp = 0;
  applyEffectInstance(world, actor, { key: "test_independent", turnsLeft: 5 });
  cleanupSystem(world);
  assert(!world.isAlive(actor));
  assertEquals([...world.query(EffectInstance)].length, 0);
  assertEquals([...world.query(PeriodicEffect)].length, 0);
});

Deno.test("stack caps scale each operation correctly while extension and replacement have distinct lifetimes", () => {
  const { world, actor } = setup();
  for (let i = 0; i < 3; i++) applyEffectInstance(world, actor, { key: "test_stack", turnsLeft: 5 });
  world.tick(1);
  assertEquals(world.get(actor, Vitality).hp, 14);
  assertEquals(world.get(actor, Mana).mana, 24);
  const extension = applyEffectInstance(world, actor, { key: "test_extend", turnsLeft: 2 });
  applyEffectInstance(world, actor, { key: "test_extend", turnsLeft: 3 });
  assertEquals(world.get(extension, Duration).turnsLeft, 5);
  const replaced = applyEffectInstance(world, actor, { key: "test_replace", turnsLeft: 5 });
  const removals = [];
